head.script:
scwin.onpageload = function() {
	requires("uiplugin.popup");
	scwin.popupIdx = 0;
	dlt_select.setJSON([
		{"label":"button","code":"button"},
		{"label":"calendar","code":"calendar"},
		{"label":"checkbox","code":"checkbox"},
		{"label":"select","code":"select"},
		{"label":"radio","code":"radio"},
		{"label":"text","code":"text"}
	]);
	sel_sample.setJSON([
		{"col1":"축구", "col2":"1"},
		{"col1":"농구", "col2":"2"},
		{"col1":"야구", "col2":"3"},
		{"col1":"배구", "col2":"4"}
	]);
	dataList1.setJSON([{"col3":"1"},{"col3":"2"},{"col3":"1"},{"col3":"1"},{"col3":"2"}]);
};

scwin.inputTypeCustomObj = {
	text: {inputType: "text"},
	calendar : {inputType : "calendar"},
	radio: {inputType : "radio"},
	checkbox : {inputType :"checkbox"},
	select : {inputType : "select",
		options : {viewType :"default", chooseOption : true, chooseOptionLabel : "-선택-"},
		itemSet : {nodeset:"data:sel_sample", label : "col1", value : "col2"}
	},
	select2 : {inputType : "select",
		options : {viewType : "icon", chooseOption : true},
		itemSet : {nodeset:"data:sel_sample", label : "col1", value : "col2"}
	},
	button : {inputType : "button", className: "test1", value: "button"}
};

//값 변경 시 col2의 inputType을 동적으로 변경한다.
scwin.gridView1_onviewchange = function(info) {
	var obj = scwin.inputTypeCustomObj[info.newValue];
	if (dataList1.getCellData(info.rowIndex, "col3") == "2") {
		obj = scwin.inputTypeCustomObj["select2"];
	}
	gridView1.setCellInputType(info.rowIndex, "col2", obj);
};

scwin.gridView_oncellclick = function(row, col, colId) {
	var inputType = this.getInputType(colId);
	if (inputType == "button") {
		scwin.openPopup("wframePopup");
	} else if (inputType === "custom") {
		var cellInfo = this.getCellInfo(col);
		var cellManager = cellInfo.cellManagerHashByRowIndex[row];
		if (cellManager && cellManager.options.inputType === "button") {
			scwin.openPopup("wframePopup");
		}
	}
};

scwin.openPopup = function(type) {
	var idx = $p.top().scwin.popupIdx;
	var pos = [["100px", "100px"], ["370px", "400px"], ["100px", "700px"]][idx % 3];
	var options = {
		id : "popup" + idx,
		type : type,
		width : "580px",
		height : "250px",
		top : pos[0],
		left : pos[1],
		popupName : type + idx + " (modaless)",
		modal : false,
		useModalStack : true,
		resizable : true,
		status : true,
		menubar : false,
		scrollbars : false,
		accessibility : true,
		title : false
	};
	// 원래 404 인 src(팝업 창 생성·닫기 확인용) 유지
	$p.openPopup("WESD_86_content1.xml", options);
	$p.top().scwin.popupIdx++;
};
